	/** 
	 * jumpstart the process by instantiating2 Refund
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		refundId = RefundService.getRefundInstance()
		.createRefund( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		RefundService.getRefundInstance()
				.createRefund( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.refundSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Refund : " + successValue.getRefundId());
							  if (successValue.getRefundId().equals(refundId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfRefundList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Refund test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on refund consumed")
					);
			subscriber.refundSubscribe( refundId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Refund : " + successValue.getRefundId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfRefundList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on refund for refundId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Refund. 
	 */
	protected Refund read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Refund" );

		Refund entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Refund with primary key" );
		msg.append( refundId );
		
		RefundFetchOneSummary fetchOneSummary = new RefundFetchOneSummary( refundId );

		try {
			entity = RefundService.getRefundInstance().getRefund( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Refund " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Refund.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Refund." );

		StringBuilder msg = new StringBuilder( "Failed to update a Refund : " );        
		Refund entity = read();
		UpdateRefundCommand command = generateUpdateCommand();
		command.setRefundId(entity.getRefundId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Refund." );

			// for use later on...
			refundId = entity.getRefundId();

			RefundService proxy = RefundService.getRefundInstance();  

			proxy.updateRefund( command ).get();

			LOGGER.info( "-- Successfully saved Refund - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + refundId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Refund.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Refund." );

		Refund entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Refund with id " + refundId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Refund with id " + refundId );

			throw e;
		}

		try{
			RefundService.getRefundInstance().delete( new DeleteRefundCommand( entity.getRefundId() ) ).get();
			LOGGER.info( "-- Successfully deleted Refund with id " + refundId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Refund with id " + refundId );

			throw e;
		}
	}

	/**
	 * get all Refunds.
	 */
	protected List<Refund> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Refunds:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Refund : " );        
		List<Refund> collection  = new ArrayList<>();

		try {
			// call the static get method on the RefundService
			collection = RefundService.getRefundInstance().getAllRefund();
			assertNotNull( collection, "An Empty collection of Refund was incorrectly returned.");
			
			// Now print out the values
			Refund entity = null;            
			Iterator<Refund> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getRefundId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

